<script setup lang="ts">
import TaskErrors from '../components/forms/TaskErrors.vue';
import { ref, onMounted } from 'vue';
import { manual } from '../stores/manual.js';
import { system } from '../stores/system.js';
import { adminRequest, identity, type CatalogReply, type AdminReply } from '../api/admin.js';
import type { ConfigurationDto } from '../types/wire.js';
const revisions = ref<{ revision: number; hash: string; timestamp_ms: number }[]>([]);
const importText = manual.importBuffer, errorScope = ref('');
async function load() { errorScope.value = 'revisions'; await manual.run(async () => { const reply = await adminRequest<AdminReply & { revisions: typeof revisions.value }>('/api/config/revisions'); revisions.value = reply.revisions; }); }
onMounted(load);
async function importCandidate() { errorScope.value = 'import'; await manual.run(async () => { const reply = await adminRequest<CatalogReply>('/api/config/import', { document: importText.value }); importText.value = JSON.stringify(reply.configuration, null, 2); }); if (!manual.issues.value.length) await manual.replaceCandidate(JSON.parse(importText.value) as ConfigurationDto); }
async function restore(revision: number) { errorScope.value = 'revisions'; let restored: ConfigurationDto | null = null; await manual.run(async () => { if (!system.stored.value) throw Error('Сохранённая версия недоступна'); const reply = await adminRequest<CatalogReply>('/api/config/restore-candidate', { revision, expected: identity(system.stored.value) }); restored = reply.configuration; }); if (restored) await manual.replaceCandidate(restored); }
function download(value: unknown, name: string) { const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
async function exportStored() { await manual.run(async () => download(await adminRequest('/api/config/export'), 'firefly-stored.json')); }
async function file(event: Event) { const selected = (event.target as HTMLInputElement).files?.[0]; if (selected) importText.value = await selected.text(); }
async function reconcile() { errorScope.value = 'recovery'; if (!confirm('Восстановить целостность ConfigStore? Это не активирует конфигурацию. Локальный план остаётся в памяти; перед применением потребуется новая проверка.')) return; await manual.run(async () => { await adminRequest('/api/config/reconcile', {}); manual.review.value = null; manual.outcome.value = 'Reconcile завершён. Проверьте stored/active; Apply не выполнялся.'; }); await system.refresh(); }
function reset() { if (confirm('Отбросить локальный план и перечитать сохранённую конфигурацию?')) void manual.reset(); }
async function migrate() { errorScope.value = 'import'; let next: ConfigurationDto | undefined; await manual.run(async () => { if (!manual.draft.value) throw Error('Конфигурация недоступна'); next = (await adminRequest<CatalogReply>('/api/config/migrate', { configuration: manual.draft.value })).configuration; }); if (next) await manual.replaceCandidate(next); }
</script>
<template><fieldset :disabled="manual.busy.value"><div class="inline-actions"><RouterLink to="/advanced/playground">Command Playground →</RouterLink><RouterLink to="/diagnostics">Диагностика →</RouterLink></div><section class="panel"><h2>Сохранённая и активная конфигурации</h2><p>Stored: {{ system.stored.value?.revision }} · {{ system.stored.value?.hash }}</p><p>Active: {{ system.active.value?.revision }} · {{ system.active.value?.hash }}</p><p>Generation: {{ system.active.value?.generation_id }}</p><button @click="exportStored">Экспорт сохранённой конфигурации</button><button :disabled="!manual.draft.value" @click="download(manual.draft.value, 'firefly-candidate.json')">Экспорт локального плана</button></section><section class="panel"><h2>Импорт в план</h2><label>JSON-файл<input type="file" accept="application/json,.json" @change="file"></label><label>Документ кандидата<textarea v-model="importText" rows="8"></textarea></label><p>Выбор файла ничего не сохраняет и не применяет. Импорт проходит полную validation; затем нужен общий review.</p><button :disabled="manual.busy.value" @click="importCandidate">Проверить импорт и добавить в план</button><button @click="importText = ''; manual.issues.value = []">Отбросить импорт</button><button v-if="manual.draft.value?.schema_version === 1" @click="migrate">Подготовить schema v2 как кандидат</button><TaskErrors v-if="errorScope === 'import'" :issues="manual.issues.value" /></section><section class="panel"><h2>Версии</h2><button @click="load">Обновить список версий</button><article v-for="revision in revisions" :key="revision.revision" class="inline-actions"><strong>Версия {{ revision.revision }}</strong><span>{{ new Date(revision.timestamp_ms).toLocaleString('ru-RU') }}</span><button :disabled="manual.busy.value" @click="restore(revision.revision)">Восстановить как кандидат</button></article><TaskErrors v-if="errorScope === 'revisions'" :issues="manual.issues.value" /></section><section class="panel"><h2>Recovery</h2><p>Reconcile восстанавливает целостность хранилища по существующим backend правилам. Runtime отдельно; silent Apply отсутствует.</p><button @click="reconcile">Reconcile хранилища</button><button @click="reset">Перечитать основу и отбросить локальный план</button><TaskErrors v-if="errorScope === 'recovery'" :issues="manual.issues.value" /></section></fieldset></template>
